import React, { useState, useEffect } from 'react';
import api from '../services/api';

interface Product {
  id: string;
  name: string;
  price: number;
  category: string;
  stockQuantity: number;
  description?: string;
}

const Shop: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [cart, setCart] = useState<{ [key: string]: number }>({});
  const [checkoutLoading, setCheckoutLoading] = useState(false);

  useEffect(() => {
    const fetchProducts = async () => {
      try {
        const response = await api.get('/products');
        setProducts(response.data.products || []);
      } catch (error) {
        console.error('Failed to fetch products', error);
        alert('Failed to load products');
      } finally {
        setLoading(false);
      }
    };

    fetchProducts();
  }, []);

  const addToCart = (productId: string) => {
    setCart({
      ...cart,
      [productId]: (cart[productId] || 0) + 1,
    });
  };

  const removeFromCart = (productId: string) => {
    if (cart[productId] <= 1) {
      const { [productId]: _, ...rest } = cart;
      setCart(rest);
    } else {
      setCart({
        ...cart,
        [productId]: cart[productId] - 1,
      });
    }
  };

  const getTotalPrice = () => {
    return Object.entries(cart).reduce((total, [productId, quantity]) => {
      const product = products.find((p) => p.id === productId);
      return total + (product?.price || 0) * quantity;
    }, 0);
  };

  const getItemCount = () => {
    return Object.values(cart).reduce((sum, qty) => sum + qty, 0);
  };

  const handleCheckout = async () => {
    if (Object.keys(cart).length === 0) {
      alert('⚠️ Cart is empty');
      return;
    }

    const totalPrice = getTotalPrice();
    if (!window.confirm(`Proceed to purchase ₹${totalPrice.toLocaleString('en-IN', { maximumFractionDigits: 2 })}?`)) {
      return;
    }

    setCheckoutLoading(true);
    try {
      let successCount = 0;
      let errorMsg = '';

      for (const [productId, quantity] of Object.entries(cart)) {
        try {
          await api.post('/sales', {
            productId,
            quantity,
            paymentMethod: 'WALLET',
          });
          successCount++;
        } catch (error: any) {
          errorMsg = error.response?.data?.message || 'Purchase failed';
          break;
        }
      }

      if (successCount === Object.keys(cart).length) {
        alert('✅ Purchase successful!');
        setCart({});
      } else {
        alert(`⚠️ Partial purchase. ${successCount} of ${Object.keys(cart).length} items purchased.\n${errorMsg}`);
        setCart({});
      }
    } catch (error: any) {
      alert(error.response?.data?.message || '❌ Purchase failed');
    } finally {
      setCheckoutLoading(false);
    }
  };

  if (loading) {
    return <div className="text-center py-12 text-slate-300">Loading products...</div>;
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-4xl font-bold bg-gradient-to-r from-cyan-400 via-blue-400 to-purple-500 bg-clip-text text-transparent mb-2">
          🛍️ Digital Shop
        </h1>
        <p className="text-slate-400">Browse and purchase digital products</p>
      </div>

      {/* Products Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {products.map((product) => (
          <div
            key={product.id}
            className="rounded-xl border border-cyan-500/30 bg-gradient-to-br from-slate-800/50 to-slate-900/50 backdrop-blur-sm overflow-hidden hover:border-cyan-400/80 transition-all duration-300 group"
          >
            {/* Product Image Placeholder */}
            <div className="bg-gradient-to-br from-slate-700 to-slate-800 h-48 flex items-center justify-center text-6xl border-b border-slate-700">
              📦
            </div>

            {/* Product Info */}
            <div className="p-6">
              <div className="flex justify-between items-start mb-2">
                <h3 className="text-lg font-bold text-slate-100 flex-1">{product.name}</h3>
                {cart[product.id] && (
                  <span className="px-2 py-1 bg-cyan-500/20 text-cyan-400 rounded text-sm font-semibold">
                    ×{cart[product.id]}
                  </span>
                )}
              </div>

              <p className="text-slate-400 text-sm mb-1">{product.category}</p>
              <p className="text-slate-400 text-xs mb-3">In Stock: {product.stockQuantity}</p>

              {/* Price */}
              <p className="text-2xl font-bold bg-gradient-to-r from-cyan-400 to-blue-400 bg-clip-text text-transparent mb-4">
                ₹{product.price.toLocaleString('en-IN', { maximumFractionDigits: 0 })}
              </p>

              {/* Add/Remove Buttons */}
              <div className="flex gap-2">
                <button
                  onClick={() => addToCart(product.id)}
                  className="flex-1 px-4 py-2 bg-gradient-to-r from-cyan-500 to-blue-600 text-white font-semibold rounded-lg hover:from-cyan-600 hover:to-blue-700 transition shadow-lg shadow-cyan-500/20 disabled:opacity-50"
                  disabled={product.stockQuantity === 0}
                >
                  Add to Cart
                </button>
                {cart[product.id] && (
                  <button
                    onClick={() => removeFromCart(product.id)}
                    className="px-4 py-2 bg-slate-700 text-slate-300 rounded-lg hover:bg-slate-600 transition"
                  >
                    Remove
                  </button>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Cart Summary */}
      {Object.keys(cart).length > 0 && (
        <div className="rounded-xl border border-cyan-500/30 bg-gradient-to-br from-slate-800/50 to-slate-900/50 backdrop-blur-sm p-8 sticky bottom-0 z-50">
          <div className="flex justify-between items-center mb-4">
            <div>
              <p className="text-slate-400">Items in Cart</p>
              <p className="text-3xl font-bold text-cyan-400">{getItemCount()} items</p>
            </div>
            <div className="text-right">
              <p className="text-slate-400">Total Amount</p>
              <p className="text-4xl font-bold bg-gradient-to-r from-cyan-400 to-blue-400 bg-clip-text text-transparent">
                ₹{getTotalPrice().toLocaleString('en-IN', { maximumFractionDigits: 2 })}
              </p>
            </div>
          </div>

          <button
            onClick={handleCheckout}
            className="w-full px-6 py-4 bg-gradient-to-r from-emerald-500 to-green-600 text-white font-bold text-lg rounded-lg hover:from-emerald-600 hover:to-green-700 transition shadow-lg shadow-emerald-500/30 disabled:opacity-50 flex items-center justify-center gap-2"
            disabled={checkoutLoading || Object.keys(cart).length === 0}
          >
            {checkoutLoading ? '⏳ Processing...' : '✓ Checkout Now'}
          </button>
        </div>
      )}

      {/* Empty Cart Message */}
      {products.length === 0 && (
        <div className="text-center py-12">
          <p className="text-slate-400 text-lg">No products available</p>
        </div>
      )}
    </div>
  );
};

export default Shop;
